# The Terraform variables of staging, from trivia-more-infra → /staging and the shared folders; sourced by infra/run.sh.
export TF_VAR_postgres_password="${STAGING_POSTGRES_PASSWORD:?add STAGING_POSTGRES_PASSWORD to trivia-more-infra → /staging}"
export TF_VAR_owner_email="${CONSOLE_OWNER_EMAIL:?add CONSOLE_OWNER_EMAIL to trivia-more-infra → /cloudflare}"
export TF_VAR_garage_rpc_secret="${GARAGE_RPC_SECRET:?add GARAGE_RPC_SECRET to trivia-more-infra → /staging}"
export TF_VAR_garage_admin_token="${GARAGE_ADMIN_TOKEN:?add GARAGE_ADMIN_TOKEN to trivia-more-infra → /staging}"
export TF_VAR_garage_app_access_key_id="${GARAGE_APP_ACCESS_KEY_ID:?add GARAGE_APP_ACCESS_KEY_ID to trivia-more-infra → /staging}"
export TF_VAR_garage_app_secret_access_key="${GARAGE_APP_SECRET_ACCESS_KEY:?add GARAGE_APP_SECRET_ACCESS_KEY to trivia-more-infra → /staging}"
export TF_VAR_infisical_site_url="${INFISICAL_SITE_URL:?add INFISICAL_SITE_URL to trivia-more-infra → /terraform}"
export TF_VAR_app_db_password="${STAGING_APP_DB_PASSWORD:?add STAGING_APP_DB_PASSWORD to trivia-more-infra → /staging}"
export INFISICAL_HOST="${TF_INFISICAL_HOST:?add TF_INFISICAL_HOST to trivia-more-infra → /terraform}"
export INFISICAL_UNIVERSAL_AUTH_CLIENT_ID="${TF_INFISICAL_CLIENT_ID:?add TF_INFISICAL_CLIENT_ID to trivia-more-infra → /terraform}"
export INFISICAL_UNIVERSAL_AUTH_CLIENT_SECRET="${TF_INFISICAL_CLIENT_SECRET:?add TF_INFISICAL_CLIENT_SECRET to trivia-more-infra → /terraform}"
